"""Oracle BI Publisher sends '.xls' attachments that are really HTML (seen on the live SIT mail, 14-Oct-2026)."""
from datetime import date
from decimal import Decimal

import pytest

from inward.importers.common import ImportFailed, detect_format
from inward.importers.sit import parse_sit

ORACLE_HTML = """<html>
<!-- Generated by Oracle BI Publisher 10.1.3.4.2 -->
<head><meta http-equiv="Content-Type" content="text/html; charset=UTF-8"/><title>RTF Template</title>
<style type="text/css">.c0 {text-align: center;}</style></head>
<body>
<p class="c0"><span>BPIL Depot Stock In Transit Report</span></p>
<p class="c2"><span>From Date :: 03-AUG-25 To Date :: 25-JUN-26</span></p>
<p class="c5"><span>System Date :: 26-JUN-2026</span></p>
<table class="c53">
<tr><td><p>From Org</p></td><td><p>To Org</p></td><td><p>Delivery Id</p></td><td><p>Shipment Period</p></td>
<td><p>Shipment Date</p></td><td><p>Item Type</p></td><td><p>Item Code</p></td><td><p>Item Desc</p></td>
<td><p>Item BL</p></td><td><p>Uom</p></td><td><p>Volume</p></td><td><p>Quantity Issued</p></td>
<td><p>Receipt Num</p></td><td><p>Receipt Date</p></td><td><p>Quantity Received</p></td></tr>
<tr><td>'092:Chennai-2</td><td>035:Coimbatore</td><td>48660113</td><td>AUG-2025</td><td>13-AUG-2025</td><td>FG</td>
<td>F004690800020000</td><td>FAST BAKE PRIMER BLACK 20 L</td><td>AUTOMOTIVE</td><td>L</td><td>20</td><td>5</td>
<td></td><td></td><td></td></tr>
<tr><td>'300:Howrah - Mfg</td><td>035:Coimbatore</td><td>50559883</td><td>JAN-2026</td><td>08-JAN-2026</td><td>FG</td>
<td>F00B470633002001</td><td>QD A/C PUTTY-GREY-2 K</td><td>AUTOMOTIVE</td><td>K</td><td>2</td><td>10</td>
<td></td><td></td><td></td></tr>
<tr><td>'300:Howrah - Mfg</td><td>035:Coimbatore</td><td>50559883</td><td>JAN-2026</td><td>08-JAN-2026</td><td>FG</td>
<td>F00B470633002001</td><td>QD A/C PUTTY-GREY-2 K</td><td>AUTOMOTIVE</td><td>K</td><td>2</td><td>60</td>
<td></td><td></td><td></td></tr>
</table><p></p></body></html>"""


def test_oracle_html_sit_named_xls(tmp_path):
    path = tmp_path / "BPIL_DEP_STK_INTRAN_863608429_1.xls"
    path.write_text(ORACLE_HTML, encoding="utf-8")
    assert detect_format(path) == "html"
    sit = parse_sit(path)
    assert (sit.window_from, sit.window_to, sit.system_date) == (date(2025, 8, 3), date(2026, 6, 25), date(2026, 6, 26))
    assert len(sit.rows) == 3 and sit.issues == []
    putty = sit.lines[("50559883", "F00B470633002001")]
    assert putty.quantity == 70 and putty.measure == Decimal("140") and putty.business_line == "AUTOMOTIVE"
    assert sit.rows[0].from_org_code == "092" and sit.rows[0].shipment_date == date(2025, 8, 13)


def test_unknown_content_is_rejected(tmp_path):
    path = tmp_path / "fake.xls"
    path.write_bytes(b"this is not a spreadsheet")
    with pytest.raises(ImportFailed):
        detect_format(path)
